      SUBROUTINE QEOCC     PRINTING OF BEAM MATRIX AND ACCUMULATED LENGTHCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLESC      CHARACTER*8     LSIUN      INTEGER         J, JMIN1, K      LOGICAL         UBIG, CDONE      REAL            ALONG, CENUN, CORR, DEN, SIUN      REAL            OUTPUT(10), SIO(6)C ---------------------------------------------------------------------CC     CUMULATIVE LENGTHC      ALONG = LC/UFLOOR(1)CC     BEAM SIZEC      IF (.NOT. RECENT) CALL BEAM      UBIG = UBEAM(1) .GT. 0.5 .AND. UBEAM(2) .GT. 0.5      IF (NORD3 .GE. 1) THEN        DO 10 J = 1, 6        SIO(J) = SQRT(SIT(J,J))   10   CONTINUE      ENDIFCC     PRINT BEAM PARAMETERSC      IF (TERSE) GO TO 100      CENUN = CEN(1)/UBEAM(1)      SIUN = 0.0      IF (NORD3 .GE. 1) SIUN = SIO(1)/UBEAM(1)      IF (SIUN .LT. 10000.0) THEN        WRITE (LSIUN,1020) SIUN 1020   FORMAT (F8.3)      ELSE        WRITE (LSIUN,1021) SIUN 1021   FORMAT (E8.2)      ENDIF      IF (LCPR) THEN        IF (NARROW) THEN          WRITE (NOUT,1023) CENUN, LSIUN, XBEAM(1) 1023     FORMAT (1H ,17X,F12.3,A8,1X,A4)        ELSE          WRITE (NOUT,1015) CENUN, LSIUN, XBEAM(1) 1015     FORMAT (1H ,67X,F12.3,A8,1X,A4)        ENDIF      ELSE        IF (NARROW) THEN          WRITE (NOUT,1024) ALONG, XFLOOR(1), CENUN, LSIUN, XBEAM(1) 1024     FORMAT (1H ,8X,F10.3,1X,A4,/,18X,F12.3,A8,1X,A4)        ELSE          WRITE (NOUT,1016) ALONG, XFLOOR(1), CENUN, LSIUN, XBEAM(1) 1016     FORMAT (1H ,8X,F10.3,1X,A4,44X,F12.3,A8,1X,A4)        ENDIF      ENDIFC   30 DO 40 J = 2, 6      JMIN1 = J - 1      CENUN = CEN(J)/UBEAM(J)      SIUN = 0.0      IF (NORD3 .GE. 1) SIUN = SIO(J)/UBEAM(J)      IF (SIUN .LT. 10000.0) THEN        WRITE (LSIUN,1020) SIUN      ELSE        WRITE (LSIUN,1021) SIUN      ENDIF      DO 35 K = 1, JMIN1      CORR = 0.0      IF (NORD3 .GE. 1) CORR = SIT(J,K)/DEN(SIO(J)*SIO(K))      OUTPUT(K) = CORR   35 CONTINUE      IF (NARROW) THEN        WRITE (NOUT,1022)     1         CENUN, LSIUN, XBEAM(J), (OUTPUT(K), K = 1, JMIN1)      ELSE        WRITE (NOUT,1014)     1         CENUN, LSIUN, XBEAM(J), (OUTPUT(K), K = 1, JMIN1)      ENDIF   40 CONTINUE 1022 FORMAT (18X,F12.3,A8,1X,A4,F9.3,4F7.3) 1014 FORMAT (68X,F12.3,A8,1X,A4,F9.3,4F7.3)      GO TO 300CC     SINGLE LINE OUTPUTC  100 CDONE = .FALSE.      IF (.NOT. NOPH .AND. NORD3 .GE. 1 .AND. .NOT. SOFA     1    .AND. .NOT. CPS) GO TO 120      IF (.NOT. CPR .AND. CPS) GO TO 120      CDONE = .TRUE.      DO 110 J = 1, 6      OUTPUT(J) = CEN(J)/UBEAM(J)  110 CONTINUE      IF (.NOT. LCPR .AND. .NOT. UBIG) THEN        WRITE (NOUT,1013) ALONG, XFLOOR(1),     1                    (OUTPUT(J), XBEAM(J), J = 1, 6)      ELSE IF (.NOT. LCPR .AND. UBIG) THEN        WRITE (NOUT,1018) ALONG, XFLOOR(1),     1                    (OUTPUT(J), XBEAM(J), J = 1, 6)      ELSE IF (LCPR .AND. .NOT. UBIG) THEN        WRITE (NOUT,1017) (OUTPUT(J), XBEAM(J), J = 1, 6)      ELSE IF (LCPR .AND. UBIG) THEN        WRITE (NOUT,1019) (OUTPUT(J), XBEAM(J), J = 1, 6)      ENDIF 1013 FORMAT (1H ,8X,F10.3,1X,A4,11X,6(F8.3,1X,A4),1X,2F9.3) 1018 FORMAT (1H ,8X,F10.3,1X,A4,5X,6(F9.6,1X,A4),1X,2F9.3) 1017 FORMAT (1H ,34X,6(F8.3,1X,A4),1X,2F9.3) 1019 FORMAT (1H ,28X,6(F9.6,1X,A4),1X,2F9.3)      LCPR = .TRUE.C  120 IF (NOPH .OR. NORD3 .LT. 1) GO TO 300      DO 130 J = 1, 6      OUTPUT(J) = SIO(J)/UBEAM(J)  130 CONTINUE      OUTPUT(7) = SIT(1,2)/DEN(SIO(1)*SIO(2))      OUTPUT(8) = SIT(3,4)/DEN(SIO(3)*SIO(4))C      IF (CDONE) THEN        IF (.NOT. UBIG) THEN          WRITE (NOUT,1012) (OUTPUT(J), J = 1, 8) 1012     FORMAT (1H ,34X,6(F8.3,5X),1X,2F9.3)        ELSE          WRITE (NOUT,1011) (OUTPUT(J), J = 1, 8) 1011     FORMAT (1H ,28X,6(F9.6,5X),1X,2F9.3)        ENDIFC      ELSE        IF (.NOT. LCPR .AND. .NOT. UBIG) THEN          WRITE (NOUT,1013) ALONG, XFLOOR(1),      1                      (OUTPUT(J), XBEAM(J), J=1, 6),     2                      OUTPUT(7), OUTPUT(8)        ELSE IF (.NOT. LCPR .AND. UBIG) THEN          WRITE (NOUT,1018) ALONG, XFLOOR(1),      1                      (OUTPUT(J), XBEAM(J), J=1, 6),     2                      OUTPUT(7), OUTPUT(8)        ELSE IF (LCPR .AND. .NOT. UBIG) THEN          WRITE (NOUT,1017) (OUTPUT(J), XBEAM(J), J = 1, 6),     1                      OUTPUT(7), OUTPUT(8)        ELSE          WRITE (NOUT,1019) (OUTPUT(J), XBEAM(J), J = 1, 6),     1                      OUTPUT(7), OUTPUT(8)        ENDIF      ENDIFC  300 LCPR = .TRUE.      BDUN = .TRUE.      RETURN      END